#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

long long get_perm(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int total_n, modulus;
    cin >> total_n >> modulus;
    if (total_n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> sequence(1, 1);
    long long total_sum = 0;
    for (int i = 2; i <= total_n; ++i) {
        int size = ((i - 1) * i) / 2 + 1;
        vector<long long> new_seq(size, 0);
        vector<long long> prefix_sum(sequence.size() + 1, 0);
        for (int idx = (int)sequence.size() - 1; idx >= 0; --idx) {
            prefix_sum[idx] = (prefix_sum[idx + 1] + sequence[idx]) % modulus;
        }
        for (int w = 0; w < size; ++w) {
            int left_idx = max(0, w + 1 - i);
            int right_idx = (int)sequence.size() - 1;
            if (right_idx + 1 < (int)prefix_sum.size()) {
                new_seq[w] = prefix_sum[left_idx] - prefix_sum[right_idx + 1];
            } else {
                new_seq[w] = prefix_sum[left_idx];
            }
            new_seq[w] %= modulus;
        }
        int prefix_size = (int)prefix_sum.size();
        vector<long long> e_arr(prefix_size, 0);
        vector<long long> f_arr(prefix_size, 0);
        for (int w = 0; w < prefix_size - 1; ++w) {
            e_arr[w + 1] = (e_arr[w] + prefix_sum[w]) % modulus;
            f_arr[w + 1] = (f_arr[w] - (long long)w * prefix_sum[w]) % modulus;
        }
        int R_idx = (int)sequence.size();
        long long temp_b_value = 0;
        int start_jj = max(0, (int)sequence.size() - i);
        for (int jj = start_jj; jj < (int)sequence.size() - 1; ++jj) {
            int L_idx = jj + 2;
            long long val = 0;
            long long e_diff = 0, f_diff = 0;
            if (R_idx < prefix_size && L_idx < prefix_size) {
                e_diff = e_arr[R_idx] - e_arr[L_idx];
                f_diff = f_arr[R_idx] - f_arr[L_idx];
            }
            val = (((e_diff * (i + 1 + jj) + f_diff) % modulus) * sequence[jj]) % modulus;
            temp_b_value = (temp_b_value + val) % modulus;
        }
        for (int jj = 0; jj < (int)sequence.size() - i; ++jj) {
            int L_idx = jj + 2;
            int R_idx = i + jj;
            long long e_diff = 0, f_diff = 0;
            if (R_idx + 1 < prefix_size && L_idx < prefix_size) {
                e_diff = e_arr[R_idx + 1] - e_arr[L_idx];
                f_diff = f_arr[R_idx + 1] - f_arr[L_idx];
            }
            long long val = (((e_diff * (i + 1 + jj) + f_diff) % modulus) * sequence[jj]) % modulus;
            temp_b_value = (temp_b_value + val) % modulus;
        }
        total_sum = (total_sum + (temp_b_value * get_perm(total_n, total_n - i)) % modulus) % modulus;
        sequence = new_seq;
    }
    cout << total_sum % modulus << "\n";
    return 0;
}

